package dev.halloween;
import java.util.*;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;
import net.minecraft.block.*;
import net.minecraft.entity.*;
import net.minecraft.entity.passive.VillagerEntity;
import net.minecraft.server.world.ServerWorld;
import net.minecraft.util.math.*;
/** Opt-in world preparation fixture. Never runs in normal user worlds. */
final class TaigaReadyDemo {
 static volatile boolean ready;static int stage,age,scene;static volatile int frame;static List<RailVehicleEntity> trains;static List<RailwayNetwork.Station> stations;static boolean finished;
 static void register(){if(!Boolean.getBoolean("halloween.taigaReady"))return;ServerTickEvents.END_SERVER_TICK.register(server->{if(finished)return;var w=server.getOverworld();if(w.getPlayers().isEmpty())return;try{if(stations==null){stations=RailwayNetwork.get(w).stations;if(Boolean.getBoolean("halloween.taigaPolish"))stage=6;if(stations.size()!=6)throw new AssertionError("six stations required");w.setTimeOfDay(11500);w.setWeather(0,120000,false,false);for(var t:RailVehicleEntity.nearby(w,new Box(-10000,-64,-10000,10000,400,10000)))if(!t.isShip()){for(var s:w.getEntitiesByClass(RailSeatEntity.class,t.getBoundingBox().expand(6),s->s.train()==t)){for(var p:List.copyOf(s.getPassengerList())){p.stopRiding();if(p instanceof VillagerEntity)p.discard();}s.discard();}t.discard();}return;}
 if(stage<6){var st=stations.get(stage);var cp=new ChunkPos(st.origin);for(int x=-4;x<=3;x++)for(int z=-4;z<=4;z++){w.getChunk(cp.x+x,cp.z+z);RailForest.warm(w,new ChunkPos(cp.x+x,cp.z+z));}
  // Refresh today's station entrances and put a small inhabited hamlet on its village side.
  RailRingDemo.placeStation(w,st);for(int h=0;h<3;h++){var site=st.pos(-32,0,5+h*22);int ground=RailTerrain.ground(w,site.getX(),site.getZ())-1;var house=new RailwayNetwork.Station(st.village,site.withY(ground),st.facing,0);var template=VillageEraPlans.template(w,h==1?"stone_home_gable":"plains_small_house_"+(h==0?1:3));if(template==null)throw new AssertionError("house template missing");var blocks=RailwayNetwork.building(w,house,h==1?"stone_home_gable":"plains_small_house_"+(h==0?1:3));for(var e:blocks.entrySet()){var state=e.getValue();if(state.isOf(Blocks.OAK_PLANKS))state=Blocks.SPRUCE_PLANKS.getDefaultState();w.setBlockState(e.getKey(),state,Block.NOTIFY_LISTENERS);}for(int x=0;x<template.size().getX();x++)for(int z=0;z<template.size().getZ();z++)for(int d=1;d<=32;d++){var p=house.pos(x,-d,z);if(w.getBlockState(p).isSolidBlock(w,p))break;w.setBlockState(p,Blocks.COBBLESTONE.getDefaultState(),Block.NOTIFY_LISTENERS);}for(int n=0;n<2;n++){var p=house.pos(template.size().getX()/2,1,template.size().getZ()+2+n);var v=EntityType.VILLAGER.create(w,SpawnReason.EVENT);v.setPosition(Vec3d.ofBottomCenter(p));v.setPersistent();v.setVillagerData(v.getVillagerData().withType(w.getRegistryManager().getOrThrow(net.minecraft.registry.RegistryKeys.VILLAGER_TYPE).getOrThrow(net.minecraft.village.VillagerType.TAIGA)));w.spawnEntity(v);}
   var from=Vec3d.of(house.pos(template.size().getX()/2,0,template.size().getZ()+1));var to=Vec3d.of(st.pos(8,0,8+h*18));double len=from.distanceTo(to);int prior=ground;for(int d=0;d<=len;d++){var p=from.lerp(to,d/len);int y=Math.clamp(RailTerrain.ground(w,(int)p.x,(int)p.z)-1,prior-1,prior+1);prior=y;for(int side=-1;side<=1;side++){var q=BlockPos.ofFloored(new Vec3d(p.x,y,p.z)).offset(st.forward(),side);var old=w.getBlockState(q);if(old.hasBlockEntity()||old.getBlock() instanceof BedBlock)continue;w.setBlockState(q,Blocks.COBBLESTONE.getDefaultState(),Block.NOTIFY_LISTENERS);for(int up=1;up<=3;up++){var s=w.getBlockState(q.up(up));if(VillageProjects.terrain(s)||s.isIn(net.minecraft.registry.tag.BlockTags.LEAVES)||s.isIn(net.minecraft.registry.tag.BlockTags.LOGS))w.setBlockState(q.up(up),Blocks.AIR.getDefaultState(),Block.NOTIFY_LISTENERS);}}}
  }
  org.slf4j.LoggerFactory.getLogger("taiga-ready").info("READY station {} at {} with three complete cottages and six taiga residents",stage+1,st.origin);stage++;return;
 }
 if(stage==6){for(var st:stations){var random=net.minecraft.util.math.random.Random.create(st.village);for(int i=0;i<40;i++){var candidate=st.pos(-55-random.nextInt(60),0,-35+random.nextInt(140));int groundY=RailTerrain.ground(w,candidate.getX(),candidate.getZ());var root=candidate.withY(groundY);if(groundY<=w.getSeaLevel()||!w.getBlockState(root.down()).isIn(net.minecraft.registry.tag.BlockTags.DIRT))continue;boolean open=true;for(int h=0;h<22;h++)if(!w.getBlockState(root.up(h)).isAir()&&!w.getBlockState(root.up(h)).isReplaceable()){open=false;break;}if(open){int height=17+random.nextInt(9);for(int y=0;y<height;y++)for(int x=0;x<2;x++)for(int z=0;z<2;z++){var q=root.add(x,y,z);if(w.getBlockState(q).isAir()||w.getBlockState(q).isReplaceable()||w.getBlockState(q).isIn(net.minecraft.registry.tag.BlockTags.LEAVES))w.setBlockState(q,Blocks.SPRUCE_LOG.getDefaultState(),Block.NOTIFY_LISTENERS);}for(int y=5;y<=height+1;y++){int radius=Math.min(5,Math.max(1,(height+2-y)/3));if(y%3==0)radius=Math.max(1,radius-1);for(int x=-radius;x<=radius+1;x++)for(int z=-radius;z<=radius+1;z++){if(Math.abs(x-.5)+Math.abs(z-.5)>radius*1.6)continue;var q=root.add(x,y,z);if(w.getBlockState(q).isAir()||w.getBlockState(q).isReplaceable())w.setBlockState(q,Blocks.SPRUCE_LEAVES.getDefaultState().with(LeavesBlock.PERSISTENT,true),Block.NOTIFY_LISTENERS);}}}}}
 var network=RailwayNetwork.get(w);var line=network.lines.getFirst();if(!line.path.closed||line.next<(int)Math.ceil(line.path.length/16))throw new AssertionError("route incomplete");trains=RailwayNetwork.startLine(w,line);for(var t:trains)if(t.kind()==0){t.dwell=100;RailDriver.ensure(w,t);}RailRingDemo.seedPassengers(w);if(trains.stream().filter(RailVehicleEntity::isSleeper).count()!=2)throw new AssertionError("two sleeper coaches");var st=stations.getFirst();var spawn=Vec3d.ofBottomCenter(st.pos(12,3,30));var p=w.getPlayers().getFirst();p.changeGameMode(net.minecraft.world.GameMode.CREATIVE);p.networkHandler.requestTeleport(spawn.x,spawn.y,spawn.z,st.facing*90,0);ready=true;stage++;return;}
 if(frame>6){var st=stations.getFirst();var p=w.getPlayers().getFirst();var spawn=Vec3d.ofBottomCenter(st.pos(12,3,30));for(int k=0;k<trains.size();k+=3){var t=trains.get(k);double stop=t.route().closest(st.center(k==0?48:16));t.distance=stop;t.dwell=1200;t.speed=0;t.setStops(t.stationStops);t.tick();for(int j=1;j<3;j++)trains.get(k+j).tick();}w.setTimeOfDay(11500);p.getAbilities().flying=false;p.sendAbilitiesUpdate();p.networkHandler.requestTeleport(spawn.x,spawn.y,spawn.z,st.facing*90,0);p.getInventory().setStack(0,new net.minecraft.item.ItemStack(VillageItems.WORLD_STATISTICS));finished=true;org.slf4j.LoggerFactory.getLogger("taiga-ready").info("PASS six stations, inhabited cottages, completed {}m forest ring, opposite trains and two sleepers",Math.round(RailwayNetwork.get(w).lines.getFirst().path.length));}
 }catch(Throwable e){finished=true;org.slf4j.LoggerFactory.getLogger("taiga-ready").error("FAIL",e);server.stop(false);}});}
 static void client(){if(!Boolean.getBoolean("halloween.taigaReady"))return;ClientTickEvents.END_CLIENT_TICK.register(c->{if(!ready||c.player==null||c.world==null)return;c.options.pauseOnLostFocus=false;c.options.hudHidden=true;if(c.currentScreen instanceof net.minecraft.client.gui.screen.GameMenuScreen)c.setScreen(null);age++;if(age==25&&frame<6){int i=frame;c.getServer().execute(()->{var st=stations.get(i);var from=Vec3d.of(st.pos(-55,22,80));var to=Vec3d.of(st.pos(8,4,28));var d=to.subtract(from);var p=c.getServer().getOverworld().getPlayers().getFirst();p.getAbilities().flying=true;p.sendAbilitiesUpdate();p.networkHandler.requestTeleport(from.x,from.y,from.z,(float)Math.toDegrees(Math.atan2(-d.x,d.z)),(float)-Math.toDegrees(Math.atan2(d.y,d.horizontalLength())));});}if(age==65&&frame<6){net.minecraft.client.util.ScreenshotRecorder.saveScreenshot(c.runDirectory,"taiga-station-"+(frame+1)+".png",c.getFramebuffer(),1,t->{});frame++;age=0;}if(frame==6){frame=7;age=0;}if(finished&&age>50)c.scheduleStop();});}
}
